package com.maidaibridge.action.impl;
import com.maidaibridge.action.AbstractMaidAction;import com.maidaibridge.action.ActionContext;import com.maidaibridge.controller.MotionPriority;
public final class HoldPositionAction extends AbstractMaidAction {private final int duration;public HoldPositionAction(String req,int timeout,int duration){super(req,"hold_position",timeout);this.duration=Math.max(1,duration);}@Override protected void onStart(ActionContext ctx){if(ctx.motion().acquire(id,MotionPriority.TASK,ctx.gameTick()).isEmpty()){fail("MOTION_BUSY");return;}ctx.motion().halt(id,ctx.maid());}@Override protected void onTick(ActionContext ctx){if(ctx.gameTick()-startTick>=duration)succeed("HELD");}@Override protected void onStop(ActionContext ctx){ctx.motion().release(id,ctx.maid());}}
